SELECT e.id_evento,e.nome_evento,e.data_final,e.cidade,e.estado,e.tag,coalesce((SELECT jsonb_agg(jsonb_build_object('km',d.percurso_evento,'unidade',d.unidade_de_medida,'tipo',d.tipo_corrida,'bloqueado',d.percurso_bloqueado) ORDER BY d.percurso_evento) FROM public.tb_evento_corridas_percursos d WHERE d.id_evento=e.id_evento),'[]'::jsonb) AS percursos FROM public.tb_evento_corridas e WHERE id_evento IN(13166,26256,28877,29231,31657,32212,32225,32603,36477,37091,37391,34834,34839,37868,38070,39970,40447,40980,41082,42782,44199,44586,45804,46817,47613,48354,48640) ORDER BY data_final